import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Applicazioni pratiche della variabile gaussiana","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/l_calcolo-delle-probabilita/le/lebicd.md","filePath":"lezioni/l_calcolo-delle-probabilita/le/lebicd.md"}`),a={name:`lezioni/l_calcolo-delle-probabilita/le/lebicd.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="applicazioni-pratiche-della-variabile-gaussiana" tabindex="-1">Applicazioni pratiche della variabile gaussiana <a class="header-anchor" href="#applicazioni-pratiche-della-variabile-gaussiana" aria-label="Permalink to “Applicazioni pratiche della variabile gaussiana”">​</a></h1><p>Partiamo da un semplice esempio: supponiamo che io debba trovare la misura della lunghezza di una parete di una stanza con la precisione di un millimetro; mi procuro un doppio decimetro e comincio a misurare: trovo che le misure che ottengo mi danno risultati fra loro leggermente diversi.</p><p>Secondo la teoria degli errori, scartando gli errori sistematici, cioè quelli dovuti agli strumenti di misurazione o ad un modo errato di misurare, avrò che in ogni misura esiste un errore casuale che mi fornirà una misura più o meno grande della misura che cerco: se ora metto queste misure su un grafico e ripetendo il procedimento moltissime volte ottengo come rappresentazione proprio una curva a campana di Gauss e la misura migliore della parete sarà data dal vertice della campana. Intendiamoci: intuitivamente la misura centrale sarà solamente la misura che ha la più alta probabilità di essere esatta, mentre per avere la probabilità che la misura sia contenuta in un certo intervallo basterà considerare l&#39;area limitata dalla gaussiana, dall&#39;asse delle <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi></mrow><annotation encoding="application/x-tex">x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span> e dalle verticali mandate dai punti estremi dell&#39;intervallo considerato.</p><p>Come esempio considerate che l&#39;area compresa fra le verticali passanti per i punti di flesso corrisponde a circa il <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>70</mn><mi mathvariant="normal">%</mi></mrow><annotation encoding="application/x-tex">70\\%</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">70%</span></span></span></span> di probabilità che la misura sia compresa in quell&#39;intervallo (con più precisione circa il <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>68</mn><mo separator="true">,</mo><mn>27</mn><mi mathvariant="normal">%</mi></mrow><annotation encoding="application/x-tex">68,27\\%</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.9444em;vertical-align:-0.1944em;"></span><span class="mord">68</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">27%</span></span></span></span>).</p><p>Cioè la curva a campana di Gauss descrive il modo in cui gli errori casuali si distribuiscono quando facciamo una qualunque misura.</p><p>Siccome in quasi tutte le scienze il concetto di misura è centrale (pensa alla statistica, alla fisica,...) abbiamo l&#39;importanza che assume la curva a campana di Gauss.</p><blockquote><p>Vista l&#39;importanza della variabile casuale Gaussiana essa viene spesso indicata come <strong>variabile casuale normale</strong>.</p></blockquote>`,7)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};